/**
 * Hand-drawn brand marks (generated from public/brand/scribbles and the sketches in
 * this session): the logo, the sidebar icons and the scribble ring/dot/bullet. Every mark
 * is a single colour (currentColor), so it takes the colour of the text around it.
 * The gradient orb is reserved for the AI assistant (see AiLogo).
 */

type SvgProps = { className?: string; title?: string };

const ink = { fill: "none", stroke: "currentColor", strokeLinecap: "round", strokeLinejoin: "round" } as const;

/** Drawn twice — once firmly, once lightly and a touch offset — like a pen going over it again. */
function Twice({ paths, width }: { paths: string[]; width: number }) {
  return (
    <>
      <g {...ink} strokeWidth={width}>
        {paths.map((d, i) => (
          <path key={i} d={d} />
        ))}
      </g>
      <g {...ink} strokeWidth={width * 0.5} opacity={0.6} transform="translate(0.9 0.7) rotate(-1.2 24 24)">
        {paths.map((d, i) => (
          <path key={i} d={d} />
        ))}
      </g>
    </>
  );
}

