/** List bullet: a tiny filled scribble. */
export function ScribbleBullet({ className }: SvgProps) {
  return (
    <svg viewBox="0 0 40 40" className={className} aria-hidden overflow="visible">
      <g {...ink}>
      <path d="M13 15 L26 12 L11 22 L29 18 L12 28 L27 26 L17 31" strokeWidth={5} />
      </g>
    </svg>
  );
}

/** The full logo: the route mark and "where to next" in handwriting (Caveat). */
export function Wordmark({ className, mark = true }: { className?: string; mark?: boolean }) {
  return (
    <span className={`inline-flex items-center gap-[0.35em] font-hand font-semibold leading-none whitespace-nowrap ${className ?? ""}`}>
      {mark && <LogoMark className="h-[1.3em] w-auto shrink-0 -my-[0.15em]" />}
      {/* Caveat's letters sit low in their line: lift them so they centre with the mark */}
      <span className="-translate-y-[0.12em]">where to next</span>
    </span>
  );
}
